"use strict";
// 最小 DOM 模拟，驱动 page.go 中的首页脚本
const fs = require("fs");
const script = fs.readFileSync("/tmp/page-script.js", "utf8");

function makeEl(id) {
  return {
    id, value: "", textContent: "", className: "", disabled: false,
    innerHTML: "", attrs: {},
    _listeners: {},
    classList: {
      _s: new Set(),
      add(c){ this._s.add(c); }, remove(c){ this._s.delete(c); },
      contains(c){ return this._s.has(c); }
    },
    setAttribute(k,v){ this.attrs[k]=v; }, getAttribute(k){ return this.attrs[k]; },
    addEventListener(t,f){ (this._listeners[t] = this._listeners[t]||[]).push(f); },
    fire(t,ev){ (this._listeners[t]||[]).forEach(f=>f(ev)); },
    scrollIntoView(){}, insertAdjacentHTML(){}, querySelectorAll(){ return []; },
    querySelector(){ return null; }, closest(){ return null; },
    reset(){ for (const k of ["description","contactName","contactInfo","source","category","priority","orderNumber","attachmentNote"]) els["f-"+k].value = ""; }
  };
}
const ids = ["ticket-form","f-description","f-contactName","f-contactInfo","f-source","f-category","f-priority","f-orderNumber","f-attachmentNote","form-notice","submit-btn","reset-btn","list-area","detail"];
const els = {};
ids.forEach(i => els[i] = makeEl(i));

// fetch 模拟：POST /api/tickets 返回可手动控制的响应
let postResolvers = [];
let postBodies = [];
global.fetch = function(url, opts) {
  if (opts && opts.method === "POST") {
    postBodies.push(JSON.parse(opts.body));
    return new Promise(res => postResolvers.push(res));
  }
  // GET /api/tickets
  return Promise.resolve({ ok: true, json: () => Promise.resolve({ tickets: [] }) });
};
function respondPost(status, data) {
  const res = postResolvers.shift();
  res({ status, json: () => Promise.resolve(data) });
}

global.document = { getElementById: id => els[id] || null };
global.window = {};

// 加载页面脚本
eval(script);

const form = els["ticket-form"], notice = els["form-notice"], submitBtn = els["submit-btn"];
const submitEv = { preventDefault(){} };
function fill(d) {
  els["f-description"].value = d.description || "";
  els["f-contactName"].value = d.contactName || "";
  els["f-contactInfo"].value = d.contactInfo || "";
  els["f-source"].value = d.source || "";
  els["f-category"].value = d.category || "";
  els["f-priority"].value = d.priority || "";
  els["f-orderNumber"].value = d.orderNumber || "";
  els["f-attachmentNote"].value = d.attachmentNote || "";
}
function values() {
  return ["description","contactName","contactInfo","source","category","priority","orderNumber","attachmentNote"]
    .map(k => els["f-"+k].value).join("|");
}
const tick = () => new Promise(r => setTimeout(r, 0));
let failures = 0;
function check(name, cond) {
  console.log((cond ? "PASS" : "FAIL") + " " + name);
  if (!cond) failures++;
}

(async () => {
  await tick(); // 初始 loadTickets

  // --- 场景1：等待期间清空重填，旧请求成功 ---
  fill({description:"第一个问题", contactName:"张三", contactInfo:"010", source:"电话", category:"账号", priority:"高", orderNumber:"007", attachmentNote:"截图1"});
  form.fire("submit", submitEv);
  check("1a 提交后按钮禁用", submitBtn.disabled === true);
  check("1b POST 已发出", postBodies.length === 1);
  const firstSubmitId = postBodies[0].submitId;

  els["reset-btn"].fire("click", {});
  check("1c 清空重填后表单已清空", values() === "||||||||");
  fill({description:"第二个问题", contactName:"李四", contactInfo:"020", source:"在线", category:"配送", priority:"低", orderNumber:"009", attachmentNote:"截图2"});
  const draftBefore = values();

  respondPost(201, {id:"TKT-000001"});
  await tick(); await tick(); await tick();
  check("1d 旧请求成功后新登记内容未被抹掉", values() === draftBefore);
  check("1e 成功提示标注属于清空重填之前且含旧工单编号",
    notice.className.includes("ok") && notice.textContent.includes("清空重填之前") && notice.textContent.includes("TKT-000001"));
  check("1f 按钮恢复可用", submitBtn.disabled === false);

  // 新登记首次提交：独立标识，成功
  form.fire("submit", submitEv);
  check("1g 新登记使用新的提交标识", postBodies.length === 2 && postBodies[1].submitId !== firstSubmitId);
  check("1h 新登记提交内容正确", postBodies[1].description === "第二个问题" && postBodies[1].orderNumber === "009");
  respondPost(201, {id:"TKT-000002"});
  await tick(); await tick(); await tick();
  check("1i 新登记成功后表单清空", values() === "||||||||");
  check("1j 新登记成功提示", notice.className.includes("ok") && notice.textContent.includes("TKT-000002") && !notice.textContent.includes("清空重填之前"));

  // --- 场景2：等待期间清空重填，旧请求失败 ---
  fill({description:"问题A", contactName:"王五", contactInfo:"030", source:"邮件", category:"退款", priority:"普通"});
  form.fire("submit", submitEv);
  els["reset-btn"].fire("click", {});
  fill({description:"问题B", contactName:"赵六", contactInfo:"040", source:"电话", category:"技术", priority:"紧急"});
  const draftB = values();
  respondPost(500, {error:"unable to save ticket"});
  await tick(); await tick(); await tick();
  check("2a 旧请求失败后新登记内容保留", values() === draftB);
  check("2b 失败提示标注属于旧提交，不误指当前登记",
    notice.className.includes("err") && notice.textContent.includes("清空重填之前") && notice.textContent.includes("500"));
  check("2c 按钮恢复可用", submitBtn.disabled === false);
  // 当前新登记仍可正常提交
  form.fire("submit", submitEv);
  respondPost(201, {id:"TKT-000003"});
  await tick(); await tick(); await tick();
  check("2d 新登记可正常提交成功", notice.className.includes("ok") && notice.textContent.includes("TKT-000003"));

  // --- 场景3：无清空重填时，失败保留内容 ---
  fill({description:"问题C", contactName:"孙七", contactInfo:"050", source:"在线", category:"账号", priority:"高"});
  const draftC = values();
  form.fire("submit", submitEv);
  respondPost(400, {error:"invalid source"});
  await tick(); await tick(); await tick();
  check("3a 无重填时失败保留原内容", values() === draftC);
  check("3b 失败提示不含旧提交字样", notice.className.includes("err") && !notice.textContent.includes("清空重填之前"));

  // --- 场景4：同一次等待中多次清空重填 ---
  fill({description:"问题D", contactName:"周八", contactInfo:"060", source:"电话", category:"配送", priority:"低"});
  form.fire("submit", submitEv);
  els["reset-btn"].fire("click", {});
  fill({description:"中间稿", contactName:"甲", contactInfo:"1", source:"在线", category:"x", priority:"低"});
  els["reset-btn"].fire("click", {});
  fill({description:"最终稿", contactName:"乙", contactInfo:"2", source:"邮件", category:"y", priority:"高"});
  const draftFinal = values();
  respondPost(201, {id:"TKT-000004"});
  await tick(); await tick(); await tick();
  check("4a 多次重填后保留的是当前这份", values() === draftFinal);
  check("4b 提示仍标注旧提交", notice.textContent.includes("清空重填之前") && notice.textContent.includes("TKT-000004"));

  // --- 场景5：等待期间清空重填，旧请求 409 冲突 ---
  fill({description:"问题E", contactName:"吴九", contactInfo:"070", source:"在线", category:"账号", priority:"普通"});
  form.fire("submit", submitEv);
  els["reset-btn"].fire("click", {});
  fill({description:"问题F", contactName:"郑十", contactInfo:"080", source:"电话", category:"退款", priority:"高"});
  const draftF = values();
  respondPost(409, {error:"submit id was already used with different content"});
  await tick(); await tick(); await tick();
  check("5a 旧请求冲突后新登记内容保留", values() === draftF);
  check("5b 冲突提示标注属于旧提交", notice.className.includes("err") && notice.textContent.includes("清空重填之前") && notice.textContent.includes("冲突"));

  // --- 场景6：无请求等待时清空重填照常工作 ---
  els["reset-btn"].fire("click", {});
  check("6a 无等待时清空重填清空内容", values() === "||||||||");
  check("6b 无等待时提示被清除", notice.className === "notice" && notice.textContent === "");

  console.log(failures === 0 ? "\nALL TESTS PASSED" : "\n" + failures + " TEST(S) FAILED");
  process.exit(failures === 0 ? 0 : 1);
})().catch(e => { console.error("HARNESS ERROR", e); process.exit(1); });
EOF
